#!/bin/bash
# A mock host with five places that hold scheduled work: user crontabs, etc/crontab,
# etc/cron.d, systemd timers (enabled via timers.target.wants) and the at queue.
SANDBOX="$1"
cd "$SANDBOX" || exit 1
mkdir -p .lm bin var/spool/cron/crontabs var/spool/cron/atjobs etc/cron.d \
         etc/systemd/system/timers.target.wants

# ---- user crontabs (no user field: the file name is the user) ----------------
cat > var/spool/cron/crontabs/alice <<'EOF'
# DO NOT EDIT THIS FILE - edit the master and reinstall.
# (/tmp/crontab.Xk2f1pQ/crontab installed on Mon Nov  2 09:14:03 2026)
# (Cron version -- $Id: crontab.c,v 2.13 1994/01/17 03:20:37 vixie Exp $)
MAILTO=alice@example.com
# m h dom mon dow command
30 7 * * 1-5   /home/alice/bin/standup-reminder
0 */4 * * *	/home/alice/bin/sync-notes --quiet
  # temporarily disabled until the migration is over
#15 3 * * 0 /home/alice/bin/old-cleanup
@reboot /home/alice/bin/start-tmux-session
EOF
cat > var/spool/cron/crontabs/deploy <<'EOF'
# DO NOT EDIT THIS FILE - edit the master and reinstall.
# (/tmp/crontab.Qm8vTr/crontab installed on Thu Oct 29 16:40:55 2026)
# (Cron version -- $Id: crontab.c,v 2.13 1994/01/17 03:20:37 vixie Exp $)
SHELL=/bin/bash
PATH=/usr/local/bin:/usr/bin:/bin

# release jobs
*/5   *   *   *   *   /srv/app/bin/queue-depth --push  >/dev/null 2>&1
10 2 * * *  /srv/app/bin/db-backup --target s3://bk/db   # nightly, see wiki
0 4 1 * *   /srv/app/bin/rotate-certs; /srv/app/bin/reload-nginx
5 0 * * *   [ "$(date +\%u)" = 1 ] && /srv/app/bin/weekly-digest
EOF
cat > var/spool/cron/crontabs/www-data <<'EOF'
# DO NOT EDIT THIS FILE - edit the master and reinstall.
# (/tmp/crontab.7bHs2L/crontab installed on Fri Sep 11 08:02:19 2026)
# (Cron version -- $Id: crontab.c,v 2.13 1994/01/17 03:20:37 vixie Exp $)
MAILTO=""
*/15 * * * * php /var/www/html/cron.php > /dev/null
EOF
chmod 600 var/spool/cron/crontabs/*

# ---- system crontabs (a user field after the five time fields) ---------------
cat > etc/crontab <<'EOF'
# /etc/crontab: system-wide crontab
# Unlike any other crontab you don't have to run the `crontab'
# command to install the new version when you edit this file
# and files in /etc/cron.d. These files also have username fields,
# that none of the other crontabs do.

SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin

# m h dom mon dow user  command
17 *	* * *	root    cd / && run-parts --report /etc/cron.hourly
25 6	* * *	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.daily; }
47 6	* * 7	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.weekly; }
52 6	1 * *	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.monthly; }
0 1 * * *  backup  /usr/local/bin/nightly-snapshot
#
EOF
cat > etc/cron.d/backup <<'EOF'
# fileserver backups
SHELL=/bin/bash
MAILTO=storage@example.com

30 1 * * 1-6   backup   /usr/local/bin/backup.sh incremental
30 1 * * 0     backup   /usr/local/bin/backup.sh full
EOF
cat > etc/cron.d/certbot <<'EOF'
# Renew certificates twice a day (the sleep spreads the load).
SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin

0 */12 * * * root test -x /usr/bin/certbot -a \! -d /run/systemd/system && perl -e 'sleep int(rand(43200))' && certbot -q renew
EOF
cat > etc/cron.d/sysstat <<'EOF'
# The first element of the path is a directory where the debian-sa1
# script is located
PATH=/usr/lib/sysstat:/usr/sbin:/usr/sbin:/usr/bin:/sbin:/bin

# Activity reports every 10 minutes everyday
5-55/10 * * * * root command -v debian-sa1 > /dev/null && debian-sa1 1 1

# Additional run at 23:59 to rotate the statistics file
59 23 * * * root command -v debian-sa1 > /dev/null && debian-sa1 60 2
EOF
cat > etc/cron.d/old.conf.dpkg-old <<'EOF'
# the pre-upgrade version, kept by dpkg: cron does not read it
0 5 * * * root /opt/legacy/purge-all
EOF
cat > etc/cron.d/.placeholder <<'EOF'
# DO NOT EDIT OR REMOVE
# This file is a simple placeholder to keep dh_installcron from removing this directory
EOF
cat > etc/cron.d/extra.disabled <<'EOF'
*/2 * * * * root /opt/legacy/poll-vendor-ftp
EOF

# ---- systemd timers (enabled = linked into timers.target.wants) --------------
U=etc/systemd/system
mkunit() {   # mkunit NAME.service DESCRIPTION [User=...] EXEC
  { printf '[Unit]\nDescription=%s\n\n[Service]\nType=oneshot\n' "$2"
    [ -n "$3" ] && printf '%s\n' "$3"
    printf 'ExecStart=%s\n' "$4"; } > "$U/$1"
}
mkunit apt-clean.service     "Clean the apt cache"     ""             "/usr/bin/apt-get clean"
mkunit db-vacuum.service     "Vacuum the database"     "User=postgres" "/usr/local/bin/db-vacuum --analyze"
mkunit fstrim.service        "Discard unused blocks"   ""             "/sbin/fstrim -av"
mkunit weekly-report.service "Weekly management report" "User=reports" "/opt/reports/weekly.sh"
mkunit cache-warm.service    "Warm the cache"          "User=app"     "/opt/app/bin/cache-warm"
mkunit legacy-sync.service   "Legacy vendor sync"      ""             "/opt/legacy/sync-vendor"
mktimer() {  # mktimer NAME DESCRIPTION ONCALENDAR [Unit=...]
  { printf '[Unit]\nDescription=%s\n\n[Timer]\nOnCalendar=%s\n' "$2" "$3"
    [ -n "$4" ] && printf '%s\n' "$4"
    printf 'Persistent=true\n\n[Install]\nWantedBy=timers.target\n'; } > "$U/$1.timer"
}
mktimer apt-clean     "Clean the apt cache daily"   "daily"
mktimer db-vacuum     "Vacuum on Sunday night"      "Sun *-*-* 03:00:00"
mktimer fstrim        "Weekly fstrim"               "weekly"
mktimer report-weekly "Monday morning report"       "Mon *-*-* 07:30:00" "Unit=weekly-report.service"
mktimer cache-warm    "Warm the cache"              "*:0/15"
mktimer legacy-sync   "Legacy vendor sync"          "hourly"
for t in apt-clean db-vacuum fstrim report-weekly; do
  ln -s "../$t.timer" "$U/timers.target.wants/$t.timer"      # cache-warm and legacy-sync are disabled
done

# ---- the at queue: Debian's spool format, listed by the atq/at mock below -----
python3 - <<'PY'
import datetime as dt, os
epoch = dt.datetime(1970, 1, 1)
jobs = [(41, "alice", 1001, dt.datetime(2026, 11, 11, 3, 0), "/usr/local/bin/rotate-keys --now"),
        (42, "deploy", 1002, dt.datetime(2026, 11, 11, 22, 30), "/srv/app/bin/db-backup --target s3://bk/db --full"),
        (43, "root", 0, dt.datetime(2026, 11, 12, 6, 0), "systemctl restart nginx")]
for n, user, uid, when, cmd in jobs:
    mins = int((when - epoch).total_seconds()) // 60
    home = "/root" if user == "root" else f"/home/{user}"
    body = (f"#!/bin/sh\n# atrun uid={uid} gid={uid}\n# mail {user} 0\numask 22\n"
            f"PATH=/usr/local/bin:/usr/bin:/bin; export PATH\nHOME={home}; export HOME\n"
            f"cd {home} || {{\n\t echo 'Execution directory inaccessible' >&2\n\t exit 1\n}}\n{cmd}\n")
    open(f"var/spool/cron/atjobs/a{n:05x}{mins:08x}", "w").write(body)
PY
cat > bin/atq <<'EOF'
#!/usr/bin/env python3
"""Mock atq / at -l / at -c for the handover exercise (jobs never run)."""
import datetime as dt, os, re, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SPOOL = os.path.join(ROOT, "var/spool/cron/atjobs")
EPOCH = dt.datetime(1970, 1, 1)
prog = os.path.basename(sys.argv[0])

def jobs():
    out = []
    for name in sorted(os.listdir(SPOOL)):
        m = re.fullmatch(r"([a-z])([0-9a-f]{5})([0-9a-f]{8})", name)
        if m:
            text = open(os.path.join(SPOOL, name)).read()
            user = re.search(r"^# mail (\S+) ", text, re.M).group(1)
            out.append((int(m.group(2), 16), EPOCH + dt.timedelta(minutes=int(m.group(3), 16)), m.group(1), user, text))
    return sorted(out, key=lambda j: j[0])

args = sys.argv[1:]
if prog == "at" and args[:1] == ["-c"]:
    want = [int(a) for a in args[1:] if a.isdigit()]
    for n, when, q, user, text in jobs():
        if n in want:
            sys.stdout.write(text)
    sys.exit(0)
if prog == "atq" or args[:1] == ["-l"]:
    for n, when, q, user, text in jobs():
        stamp = when.strftime("%a %b ") + format(when.day, "2d") + when.strftime(" %H:%M:%S %Y")
        print(f"{n}\t{stamp} {q} {user}")
    sys.exit(0)
print(f"{prog}: mock: only atq, at -l and at -c are supported", file=sys.stderr)
sys.exit(1)
EOF
chmod +x bin/atq
ln -sf atq bin/at

# fingerprint of every source so the check can tell the inventory was not made by editing them
find var etc -type f -o -type l | sort | while read -r f; do
  if [ -L "$f" ]; then echo "L $f $(readlink "$f")"; else echo "F $f $(sha256sum < "$f" 2>/dev/null | cut -d' ' -f1 || shasum -a 256 < "$f" | cut -d' ' -f1)"; fi
done > .lm/sources.txt

cat > HANDOVER.txt <<'EOF'
Night shift handover, host app-07 (scheduling inventory)

The night team wants one list of everything that will run on its own on this host.
Scheduled work lives in five places here:
  var/spool/cron/crontabs/<user>   user crontabs (the file name is the owner)
  etc/crontab                      system crontab
  etc/cron.d/*                     more system crontabs
  etc/systemd/system/*.timer       systemd timers (enabled = linked in timers.target.wants)
  the at queue                     bin/atq and bin/at -c are mocks for the real tools

Write inventory.tsv: one row per scheduled item, four tab-separated columns, no header:
  source    where it comes from: the path relative to this directory
            (var/spool/cron/crontabs/alice, etc/cron.d/backup,
            etc/systemd/system/fstrim.timer), or at:<job number> for at jobs
  user      the owner: the user crontab's file name, the user field of a system
            crontab, the timer's service User= (root if it has none), the at job's owner
  schedule  cron: the five time fields (or the @word) separated by single spaces;
            timer: its OnCalendar value; at: the run time as YYYY-MM-DD HH:MM
  command   cron: everything after the time fields (and the user), as written;
            timer: the ExecStart of the service it starts; at: the command the job runs
Only things cron, systemd or atd would really run: no comments, blank lines or
VAR=value lines, no disabled timers, no files cron ignores. The rows may be in any order.
EOF
